(function(){
'use strict';
const esc=s=>window.DaydreamDB.escape(s);
const chevron='<svg viewBox="0 0 16 16" width="12" height="12" aria-hidden="true"><path d="m4 6 4 4 4-4" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>';
function dropdown(name,trigger,items){return `<div class="workspace-dropdown" data-menu-group="${name}"><div class="workspace-menu-heading">${trigger}<button type="button" class="workspace-menu-toggle" data-menu-toggle="${name}" aria-label="Open ${name} menu" aria-expanded="false" aria-controls="workspace-${name}-menu">${chevron}</button></div><div id="workspace-${name}-menu" class="workspace-menu" aria-label="${name} options">${items}</div></div>`;}
function header({world=null,mode='overview'}={}){
 const brand=`<a href="#home" class="writer-brand" aria-label="Daydream home"><span class="brand-mark">d.</span><span class="brand-name ${world?'world-brand-name':''}" ${world?`title="${esc(world.name)}"`:''}>${esc(world?.name||'daydream')}</span></a>`;
 const canvas=mode==='capture'?`<a href="${world?'#world/'+encodeURIComponent(world.id)+'/canvas':'#workspace'}" title="Return to canvas">Canvas</a>`:world?dropdown('canvas',`<button type="button" data-work="canvas" title="Return to this world’s canvas" class="${mode==='canvas'?'active':''}">Canvas</button>`,`<button type="button" data-work="add">Add section</button><button type="button" data-work="library">Library</button>`):'';
 const account=dropdown('account','<button type="button" data-account-open>Account</button>','<button type="button" data-auth-logout>Log out</button>');
 const help=dropdown('help','<button type="button" class="workspace-help-trigger" data-menu-toggle="help" aria-label="Workspace help" aria-expanded="false" aria-controls="workspace-help-menu">?</button>','<button type="button" data-guide-start>Workspace guide</button><button type="button" data-tutorial-open>Slideshow tutorial</button><button type="button" data-pause>Pause and return to now</button>').replace(/<button type="button" class="workspace-menu-toggle"[^>]*>[\s\S]*?<\/button>/,'');
 return `<header class="writer-header compact-header">${brand}<button type="button" class="workspace-nav-toggle" data-mobile-nav aria-expanded="false" aria-controls="workspace-navigation">All Worlds ${chevron}</button><nav id="workspace-navigation" class="writer-actions" aria-label="Workspace navigation"><a href="#workspace" class="all-worlds-link" title="Open all your alternative realities">All Worlds</a>${canvas}<a href="#capture" ${mode==='capture'?'aria-current="page" class="active"':''} title="Capture a quick thought">Dream Capture</a>${account}${isMobile()?'':help}</nav>${isMobile()?help:''}</header>`;
}
function closeMenus(except){document.querySelectorAll('.workspace-dropdown').forEach(group=>{if(group===except)return;group.classList.remove('menu-open');group.querySelectorAll('[data-menu-toggle]').forEach(b=>b.setAttribute('aria-expanded','false'));});}
function openMenu(name){if(isMobile()){if(name==='help')closeNavigation();else openNavigation();}const group=document.querySelector(`[data-menu-group="${name}"]`);if(!group)return;closeMenus(group);group.classList.add('menu-open');group.querySelectorAll('[data-menu-toggle]').forEach(b=>b.setAttribute('aria-expanded','true'));return group;}
const isMobile=()=>!!window.matchMedia?.('(max-width:760px)').matches;
function openNavigation(){if(!isMobile())return;const header=document.querySelector('.compact-header');header?.classList.add('navigation-open');header?.querySelector('[data-mobile-nav]')?.setAttribute('aria-expanded','true');}
function closeNavigation(){document.querySelectorAll('.compact-header').forEach(header=>{header.classList.remove('navigation-open');header.querySelector('[data-mobile-nav]')?.setAttribute('aria-expanded','false');});}
document.addEventListener('click',e=>{const mobile=e.target.closest('[data-mobile-nav]');if(mobile){const opened=mobile.getAttribute('aria-expanded')==='true';closeMenus();closeNavigation();if(!opened)openNavigation();return;}if(!e.target.closest('.compact-header')||e.target.closest('.writer-actions a,.writer-actions button:not([data-menu-toggle])'))closeNavigation();const toggle=e.target.closest('[data-menu-toggle]');if(toggle){const group=toggle.closest('.workspace-dropdown'),was=group.classList.contains('menu-open');closeMenus();if(!was)openMenu(toggle.dataset.menuToggle);return;}if(!e.target.closest('.workspace-dropdown')||e.target.closest('.workspace-menu button,.workspace-menu a'))closeMenus();});
document.addEventListener('pointerover',e=>{const group=e.target.closest('.workspace-dropdown');if(!isMobile()&&group&&e.pointerType!=='touch'&&!group.contains(e.relatedTarget))openMenu(group.dataset.menuGroup);});
document.addEventListener('pointerout',e=>{const group=e.target.closest('.workspace-dropdown');if(!isMobile()&&group&&e.pointerType!=='touch'&&!group.contains(e.relatedTarget))closeMenus();});
document.addEventListener('keydown',e=>{const group=e.target.closest('.workspace-dropdown');if(e.key==='Escape'){const mobile=document.querySelector('.compact-header.navigation-open [data-mobile-nav]');closeMenus();closeNavigation();if(mobile){e.preventDefault();mobile.focus();return;}if(group){e.preventDefault();group.querySelector('button,a')?.focus();}return;}if(isMobile()&&group?.dataset.menuGroup!=='help'&&e.target.closest('.compact-header')&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();openNavigation();const header=e.target.closest('.compact-header'),items=[...header.querySelectorAll('.writer-actions a,.writer-actions button')].filter(b=>!b.disabled&&(!b.closest('.workspace-menu')||b.closest('.workspace-dropdown')?.classList.contains('menu-open'))),i=e.target.hasAttribute('data-mobile-nav')?-1:items.indexOf(document.activeElement),offset=e.key==='ArrowDown'?1:-1;items[i<0?(offset===1?0:items.length-1):(i+offset+items.length)%items.length]?.focus();return;}if(!group)return;const items=[...group.querySelectorAll('.workspace-menu button,.workspace-menu a')].filter(b=>!b.disabled);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();openMenu(group.dataset.menuGroup);const i=items.indexOf(document.activeElement),offset=e.key==='ArrowDown'?1:-1;items[(i<0?(offset===1?0:items.length-1):(i+offset+items.length)%items.length)]?.focus();}});
document.addEventListener('focusout',()=>{if(isMobile())return;queueMicrotask(()=>{document.querySelectorAll('.workspace-dropdown.menu-open').forEach(g=>{if(!g.contains(document.activeElement)&&!g.matches(':hover')){g.classList.remove('menu-open');g.querySelectorAll('[data-menu-toggle]').forEach(b=>b.setAttribute('aria-expanded','false'));}});});});
document.addEventListener('keydown',e=>{if(e.key!=='Tab'||!isMobile())return;setTimeout(()=>{const header=document.querySelector('.compact-header');if(header&&!header.contains(document.activeElement)){closeNavigation();closeMenus();}},0);});
function syncLayout(){const header=document.querySelector('.compact-header'),help=header?.querySelector('[data-menu-group="help"]'),nav=header?.querySelector('.writer-actions');if(!help||!nav)return;const parent=isMobile()?header:nav;if(help.parentElement!==parent)parent.append(help);}
const announced=new Set();
function saveState(){const el=document.getElementById('document-save-state'),ctx=window.DaydreamWorkspace?.context?.();if(!el||!ctx?.document)return;const repo=window.DaydreamRepository,dirty=window.DaydreamStoryEditor?.hasUnsaved(),active=repo.active;
 const pending=repo.isAccount&&(active.queue?.length||active.error);
 if(dirty||pending){el.hidden=true;return;}
 if(ctx.document.isDraft){el.hidden=true;return;}
 const id=(window.DaydreamAuth?.user?.uid||'guest')+'/'+ctx.document.id;
 el.hidden=false;el.title=repo.isAccount?'Saved to your account':'Saved on this device';
 if(!announced.has(id)){el.setAttribute('aria-live','polite');el.textContent='Saved';announced.add(id);}else{el.setAttribute('aria-live','off');if(el.textContent!=='Saved')el.textContent='Saved';}
}
window.addEventListener('daydream:storage-status',saveState);
window.addEventListener('resize',()=>{closeNavigation();closeMenus();syncLayout();});
window.DaydreamWorkspaceUI={header,openMenu,closeMenus,saveState,openNavigation,closeNavigation,isMobile};
})();
